#include "Kernel/SmpTopology.hpp"
#include <cstdio>
using namespace Davis;
int main(){AcpiMadt::State m{};m.valid=true;m.cpuCount=4;m.enabledCpuCount=4;for(u32 i=0;i<4;i++){m.cpus[i].enabled=true;m.cpus[i].apicId=i;m.cpus[i].acpiUid=10+i;}SmpTopology::State s{};if(!SmpTopology::Build(m,0,s)||s.cpuCount!=4||s.onlineCount!=1)return 1;for(u32 i=1;i<4;i++)if(!SmpTopology::BeginStartup(s,i))return 2;if(!SmpTopology::MarkOnline(s,1)||!SmpTopology::MarkOnline(s,2)||!SmpTopology::MarkFailed(s,3))return 3;if(s.onlineCount!=3||!SmpTopology::AllApplicationProcessorsSettled(s))return 4;if(!SmpTopology::BeginStartup(s,3)||!SmpTopology::MarkFailed(s,3)||!SmpTopology::BeginStartup(s,3)||!SmpTopology::MarkFailed(s,3))return 5;if(SmpTopology::BeginStartup(s,3))return 6;AcpiMadt::State dup=m;dup.cpus[2].apicId=1;SmpTopology::State bad{};if(SmpTopology::Build(dup,0,bad))return 7;for(int n=0;n<10000;n++){SmpTopology::State x{};if(!SmpTopology::Build(m,0,x))return 8;for(u32 i=1;i<4;i++){if(!SmpTopology::BeginStartup(x,i)||!SmpTopology::MarkOnline(x,i))return 9;}if(x.onlineCount!=4||!SmpTopology::AllApplicationProcessorsSettled(x))return 10;}std::puts("PASS smp_topology cpus=4 cycles=10000 bounded_retries=3");return 0;}
